    content: ":";
}

/* -- option lists ---------------------------------------------------------- */

dl.option-list {
    margin-left: 40px;
}

dl.option-list > dt {
    font-weight: normal;
}

span.option {
    white-space: nowrap;
}

/* -- lists ----------------------------------------------------------------- */

/* -- compact and simple lists: no margin between items -- */

.simple  li, .compact li,
.simple  ul, .compact ul,
.simple  ol, .compact ol,
.simple > li p, .compact > li p,
dl.simple > dd, dl.compact > dd {
    margin-top: 0;
