/*
 * Sphinx stylesheet -- traditional docs.python.org theme.
 */

body {
    color: #000;
    margin: 0;
    padding: 0;
}

/* :::: LAYOUT :::: */

div.documentwrapper {
    float: left;
    width: 100%;
}

div.bodywrapper {
    margin: 0 {{ theme_sidebarwidth|todim }} 0 0;
}

div.body {
    min-width: {{ theme_body_min_width|todim }};
    max-width: {{ theme_body_max_width|todim }};
    background-color: white;
    padding: 0 20px 30px 20px;
}

div.sphinxsidebarwrapper {
    border: 1px solid #99ccff;
    padding: 10px;
    margin: 10px 15px 10px 0;
}

div.sphinxsidebar {
    float: right;
    margin-left: -100%;
    width: {{ theme_sidebarwidth|todim }};
}

div.clearer {
    clear: both;
}

div.footer {
    clear: both;
    width: 100%;
    background-color: #99ccff;
    padding: 9px 0 9px 0;
    text-align: center;
}

div.related {
    background-color: #99ccff;
    color: #333;
    width: 100%;
    height: 30px;
    line-height: 30px;
    border-bottom: 5px solid white;
}

div.related h3 {
    display: none;
}

div.related ul {
    margin: 0;
    padding: 0 0 0 10px;
    list-style: none;
}

div.related li {
    display: inline;
    font-weight: bold;
}

div.related li.right {
    float: right;
    margin-right: 5px;
}

/* ::: SIDEBAR :::: */
div.sphinxsidebar h3 {
    margin: 0;
}

div.sphinxsidebar h4 {
    margin: 5px 0 0 0;
}

div.sphinxsidebar p.topless {
    margin: 5px 10px 10px 10px;
}

div.sphinxsidebar ul {
    margin: 10px;
    margin-left: 15px;
    padding: 0;
}

div.sphinxsidebar ul ul {
    margin-top: 0;
    margin-bottom: 0;
}

div.sphinxsidebar form {
    margin-top: 10px;
}


/* :::: SEARCH :::: */
ul.search {
    margin: 10px 0 0 20px;
    padding: 0;
}

ul.search li {
    padding: 5px 0 5px 20px;
    background-image: url(file.png);
    background-repeat: no-repeat;
    background-position: 0 7px;
}

ul.search li a {
    font-weight: bold;
}

ul.search li div.context {
    color: #888;
    margin: 2px 0 0 30px;
    text-align: left;
}

ul.keywordmatches li.goodmatch a {
    font-weight: bold;
}

/* :::: COMMON FORM STYLES :::: */

div.actions {
    border-top: 1px solid #aaa;
    background-color: #ddd;
    margin: 10px 0 0 -20px;
    padding: 5px 0 5px 20px;
}

form dl {
    color: #333;
}

form dt {
    clear: both;
    float: left;
    min-width: 110px;
    margin-right: 10px;
    padding-top: 2px;
}

input#homepage {
    display: none;
}

div.error {
    margin: 5px 20px 0 0;
    padding: 5px;
    border: 1px solid #d00;
    /*border: 2px solid #05171e;
    background-color: #092835;
    color: white;*/
    font-weight: bold;
}

/* :::: INLINE COMMENTS :::: */

div.inlinecommentswrapper {
    float: right;
    max-width: 40%;
}

div.commentmarker {
    float: right;
    background-image: url(style/comment.png);
    background-repeat: no-repeat;
    width: 25px;
    height: 25px;
    text-align: center;
    padding-top: 3px;
}

div.nocommentmarker {
    float: right;
    background-image: url(style/nocomment.png);
    background-repeat: no-repeat;
    width: 25px;
    height: 25px;
}

div.inlinecomments {
    margin-left: 10px;
    margin-bottom: 5px;
    background-color: #eee;
    border: 1px solid #ccc;
    padding: 5px;
}

div.inlinecomment {
    border-top: 1px solid #ccc;
    padding-top: 5px;
    margin-top: 5px;
}

.inlinecomments p {
    margin: 5px 0 5px 0;
}

.inlinecomments .head {
    font-weight: bold;
}

.inlinecomments .meta {
    font-style: italic;
}


/* :::: COMMENTS :::: */

div#comments h3 {
    border-top: 1px solid #aaa;
    padding: 5px 20px 5px 20px;
    margin: 20px -20px 20px -20px;
    background-color: #ddd;
}

